package sylva.ui;

import sylva.model.*;
import sylva.model.Rules.*;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;

/** Java2D isometric forest, battlefield, animated guardians, and projectiles. */
public final class ForestCanvas extends JPanel {
    private final GameEngine game;private BufferedImage groundCache;private Dimension cachedSize;private TowerKind building;private long frame;private final Random detail=new Random(1741);private int hoverCol=-1,hoverRow=-1;
    public ForestCanvas(GameEngine game){this.game=game;setOpaque(true);setBackground(new Color(48,53,45));setPreferredSize(new Dimension(920,640));setToolTipText("Choose a guardian and plant it on an open forest tile beside the pale trail.");addMouseMotionListener(new MouseMotionAdapter(){@Override public void mouseMoved(MouseEvent e){int[] p=cellAt(e.getPoint());hoverCol=p[0];hoverRow=p[1];repaint();}});addMouseListener(new MouseAdapter(){@Override public void mouseExited(MouseEvent e){hoverCol=hoverRow=-1;repaint();}@Override public void mouseClicked(MouseEvent e){if(e.getButton()!=MouseEvent.BUTTON1)return;int[] p=cellAt(e.getPoint());if(p[0]<0)return;Tower existing=game.towerAt(p[0],p[1]);if(existing!=null){building=null;game.select(existing.id);firePropertyChange("selection",-1,existing.id);}else if(building!=null){if(game.place(building,p[0],p[1])){firePropertyChange("selection",-1,game.selectedTowerId);repaint();}}}});}
    public void setBuilding(TowerKind kind){building=kind;setCursor(kind==null?Cursor.getDefaultCursor():Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR));repaint();}
    public TowerKind building(){return building;}
    @Override protected void paintComponent(Graphics raw){super.paintComponent(raw);Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setRenderingHint(RenderingHints.KEY_RENDERING,RenderingHints.VALUE_RENDER_QUALITY);paintAtmosphere(g);ensureGround();g.drawImage(groundCache,0,0,null);paintCanopy(g);paintWorldObjects(g);paintEffects(g);paintVignette(g);g.dispose();frame++;}
    private double tileW(){return Math.min(56,(getWidth()-84)/14.8);}private double tileH(){return tileW()*.49;}private double ox(){return getWidth()/2.0;}private double oy(){return Math.max(55,(getHeight()-tileH()*14)/2.0-8);}
    private Point2D.Double project(double col,double row){double w=tileW(),h=tileH();return new Point2D.Double(ox()+(col-row)*w*.5,oy()+(col+row-14)*h*.5);}
    private int[] cellAt(Point p){double u=(p.x-ox())/(tileW()*.5),v=(p.y-oy())/(tileH()*.5)+14;int c=(int)Math.floor((u+v)*.5+.5),r=(int)Math.floor((v-u)*.5+.5);if(c<0||c>=17||r<0||r>=13)return new int[]{-1,-1};Point2D.Double center=project(c,r);double dx=Math.abs(p.x-center.x)/(tileW()*.5),dy=Math.abs(p.y-center.y)/(tileH()*.5);return dx+dy<=1.18?new int[]{c,r}:new int[]{-1,-1};}
    private Polygon diamond(double c,double r,double scale){Point2D.Double p=project(c,r);double w=tileW()*.5*scale,h=tileH()*.5*scale;return new Polygon(new int[]{(int)p.x,(int)(p.x+w),(int)p.x,(int)(p.x-w)},new int[]{(int)(p.y-h),(int)p.y,(int)(p.y+h),(int)p.y},4);}
    private void paintAtmosphere(Graphics2D g){GradientPaint sky=new GradientPaint(0,0,new Color(62,68,57),0,getHeight(),new Color(40,48,41));g.setPaint(sky);g.fillRect(0,0,getWidth(),getHeight());for(int i=0;i<65;i++){double x=(i*137.31+frame*.09)%Math.max(1,getWidth()),y=(i*91.7+Math.sin(frame*.018+i)*9)%Math.max(1,getHeight());g.setColor(new Color(224,232,197,(int)(24+Math.sin(frame*.03+i)*15)));g.fill(new Ellipse2D.Double(x,y,1.5+(i%3),1.5+(i%3)));}}
    private void ensureGround(){if(groundCache!=null&&getSize().equals(cachedSize))return;cachedSize=getSize();groundCache=new BufferedImage(Math.max(1,getWidth()),Math.max(1,getHeight()),BufferedImage.TYPE_INT_ARGB);Graphics2D g=groundCache.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);paintIsland(g);g.dispose();}
    private void paintIsland(Graphics2D g){Rules.World w=game.world();Color dark=new Color(23,31,23),edge=new Color(35,43,31),moss=new Color(74,91,54);Polygon outer=new Polygon();double[][] corners={{-.5,-.5},{16.5,-.5},{16.5,12.5},{-.5,12.5}};for(double[] c:corners){Point2D.Double p=project(c[0],c[1]);outer.addPoint((int)p.x,(int)p.y+28);}g.setColor(new Color(17,25,19,105));g.fillPolygon(translate(outer,10,19));g.setColor(dark);g.fillPolygon(translate(outer,0,22));g.setColor(edge);g.drawPolygon(translate(outer,0,22));g.setColor(moss);g.drawPolygon(outer);
        for(int sum=0;sum<=28;sum++)for(int c=0;c<17;c++){int r=sum-c;if(r<0||r>=13)continue;Point2D.Double p=project(c,r);Polygon tile=diamond(c,r,1);boolean path=w.walkable()[r][c],rock=w.obstacles().contains(new BuildCell(c,r));Color base=path?new Color(126,122,96):rock?new Color(77,82,65):new Color(62+(c*7+r*3)%13,78+(c*3+r*5)%15,48+(c*5+r*7)%9);g.setColor(base);g.fillPolygon(tile);g.setColor(path?new Color(175,169,137):new Color(124,137,86,85));g.drawPolygon(tile);if(path){g.setColor(new Color(211,202,164));Polygon inset=diamond(c,r,.78);g.fillPolygon(inset);g.setColor(new Color(150,144,112));g.drawPolygon(inset);g.setColor(new Color(243,232,187,65));g.drawLine((int)p.x-8,(int)p.y-2,(int)p.x+3,(int)p.y+2);}else if(!rock){detail.setSeed(c*119L+r*919L);Shape old=g.getClip();g.clip(tile);for(int i=0;i<9;i++){int x=(int)p.x+detail.nextInt((int)Math.max(1,tileW()))-(int)tileW()/2,y=(int)p.y+detail.nextInt((int)Math.max(1,tileH()))-(int)tileH()/2;g.setColor(new Color(130+detail.nextInt(45),143+detail.nextInt(40),83+detail.nextInt(28),95));g.drawLine(x,y,x+detail.nextInt(9)-4,y-2-detail.nextInt(9));}g.setClip(old);}if(rock)paintRock(g,p,c,r);}
        paintTrail(g,w.path());}
    private Polygon translate(Polygon p,int dx,int dy){Polygon q=new Polygon();for(int i=0;i<p.npoints;i++)q.addPoint(p.xpoints[i]+dx,p.ypoints[i]+dy);return q;}
    private void paintRock(Graphics2D g,Point2D.Double p,int c,int r){g.setColor(new Color(31,42,30,110));g.fillOval((int)p.x-15,(int)p.y-1,31,15);for(int i=0;i<3;i++){int dx=(i-1)*9,dy=(i%2)*-6;g.setPaint(new GradientPaint((float)p.x+dx,(float)p.y+dy-11,new Color(132,139,111),(float)p.x+dx,(float)p.y+dy+5,new Color(67,79,58)));g.fillRoundRect((int)p.x+dx-8,(int)p.y+dy-13,17,14,8,8);g.setColor(new Color(188,197,157,65));g.drawArc((int)p.x+dx-5,(int)p.y+dy-11,11,7,25,120);}}
    private void paintTrail(Graphics2D g,List<BuildCell> cells){if(cells.size()<2)return;Path2D trail=new Path2D.Double();for(int i=0;i<cells.size();i++){BuildCell c=cells.get(i);Point2D.Double p=project(c.col(),c.row());if(i==0)trail.moveTo(p.x,p.y);else trail.lineTo(p.x,p.y);}g.setStroke(new BasicStroke((float)(tileW()*.60),BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(75,71,53,130));g.draw(trail);g.setStroke(new BasicStroke((float)(tileW()*.48),BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(193,184,146));g.draw(trail);g.setStroke(new BasicStroke((float)(tileW()*.40),BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(213,205,169));g.draw(trail);g.setStroke(new BasicStroke(1));}
    private void paintCanopy(Graphics2D g){double w=tileW(),h=tileH();for(int i=0;i<9;i++){double c=-.2+i*2.1,r=-.9;Point2D.Double p=project(c,r);double sway=Math.sin(frame*.025+i)*2;g.setColor(new Color(20,31,22,100));g.fillOval((int)p.x-18,(int)p.y+30,38,12);g.setStroke(new BasicStroke((float)Math.max(5,w*.13),BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(63,58,39));g.drawLine((int)p.x,(int)p.y+26,(int)(p.x+sway),(int)p.y-38);g.setStroke(new BasicStroke(1));for(int k=0;k<8;k++){double a=k*Math.PI/4;int lx=(int)(p.x+sway+Math.cos(a)*w*.30),ly=(int)(p.y-40+Math.sin(a)*h*.5);g.setPaint(new GradientPaint(lx,ly-8,new Color(160,178,105),lx,ly+8,new Color(67,97,54)));g.fill(new Ellipse2D.Double(lx-w*.22,ly-h*.29,w*.45,h*.58));g.setColor(new Color(204,211,154,65));g.drawArc(lx-(int)w/8,ly-(int)h/5,(int)w/3,(int)h/3,30,110);}}
        Point2D.Double heart=project(16,7);for(int i=0;i<7;i++){double a=i*Math.PI*2/7;int bx=(int)(heart.x+Math.cos(a)*w*.24),by=(int)(heart.y+Math.sin(a)*h*.3);g.setStroke(new BasicStroke((float)Math.max(4,w*.10),BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(58,52,36));g.drawLine((int)heart.x,(int)heart.y+12,bx,by-30);g.setStroke(new BasicStroke(1));g.setColor(new Color(64,94,50));g.fillOval(bx-(int)w/3,by-42,(int)(w*.67),(int)(h*.7));}}
    private void paintWorldObjects(Graphics2D g){Map<Integer,ArrayList<Runnable>> depth=new TreeMap<>();for(Tower t:game.towers)depth.computeIfAbsent(t.col+t.row,k->new ArrayList<>()).add(()->paintTower(g,t,false));for(Invader e:game.enemies)depth.computeIfAbsent((int)Math.round(e.x+8+e.z+6),k->new ArrayList<>()).add(()->paintInvader(g,e));for(ArrayList<Runnable> draw:depth.values())for(Runnable d:draw)d.run();for(Projectile p:game.projectiles.values())paintProjectile(g,p);if(building!=null&&hoverCol>=0){boolean valid=game.canPlace(building,hoverCol,hoverRow);Point2D.Double p=project(hoverCol,hoverRow);g.setColor(valid?new Color(205,229,163,110):new Color(211,123,105,110));g.fill(diamond(hoverCol,hoverRow,1));paintTower(g,new Tower(-1,building,hoverCol,hoverRow,game.time),true);Point2D.Double center=project(hoverCol,hoverRow);g.setColor(new Color(223,235,195,80));g.draw(new Ellipse2D.Double(center.x-tileW()*.45,center.y-tileW()*.45,tileW()*.9,tileW()*.9));}}
    private void paintTower(Graphics2D g,Tower t,boolean ghost){Point2D.Double p=project(t.col,t.row);int s=(int)(tileW()*.46);g.setColor(new Color(15,22,16,ghost?35:100));g.fillOval((int)p.x-s/2,(int)p.y-s/5,s,s/2);if(t.kind==TowerKind.CANNON){g.setColor(new Color(89,87,67));g.fillRoundRect((int)p.x-s/2,(int)p.y-s/2,s,s/2,10,10);g.setColor(new Color(122,119,90));for(int i=0;i<4;i++)g.fillRect((int)p.x-s/2+i*s/3,(int)p.y-s/2-5,s/5,7);g.setColor(new Color(52,53,40));g.fillOval((int)p.x-4,(int)p.y-s/2-9,8,20);}else{g.setColor(new Color(99,95,67));g.fillRoundRect((int)p.x-s/2,(int)p.y-s/2,s,s/2,8,8);g.setColor(new Color(t.kind.color));if(t.kind==TowerKind.ARCHER){g.setStroke(new BasicStroke(3));g.drawArc((int)p.x-s/3,(int)p.y-s,s*2/3,s,45,270);g.drawLine((int)p.x,(int)p.y-s/2,(int)p.x+s/3,(int)p.y-s-9);}else if(t.kind==TowerKind.FROST){Polygon crystal=new Polygon(new int[]{(int)p.x,(int)p.x+8,(int)p.x+3,(int)p.x-4},new int[]{(int)p.y-s-15,(int)p.y-s+2,(int)p.y-s+9,(int)p.y-s},4);g.fillPolygon(crystal);g.setColor(new Color(236,249,236,170));g.drawLine((int)p.x,(int)p.y-s-10,(int)p.x,(int)p.y-s+5);}else{g.setStroke(new BasicStroke(3));g.drawLine((int)p.x,(int)p.y-s+4,(int)p.x+s/5,(int)p.y-s/2);g.drawLine((int)p.x+s/5,(int)p.y-s/2,(int)p.x-s/6,(int)p.y-s/4);g.drawLine((int)p.x-s/6,(int)p.y-s/4,(int)p.x+s/4,(int)p.y-s-6);}g.setStroke(new BasicStroke(1));}if(!ghost&&t.id==game.selectedTowerId){g.setColor(new Color(230,238,197,155));g.setStroke(new BasicStroke(1.4f));g.draw(new Ellipse2D.Double(p.x-t.stats.range*tileW()*.28,p.y-t.stats.range*tileW()*.28,t.stats.range*tileW()*.56,t.stats.range*tileW()*.56));g.setStroke(new BasicStroke(1));}g.setColor(new Color(234,225,191));g.setFont(getFont().deriveFont(Font.BOLD,10f));if(!ghost)g.drawString(""+t.level,(int)p.x+5,(int)p.y-4);}
    private void paintInvader(Graphics2D g,Invader e){Point2D.Double p=project(e.x+8,e.z+6);int s=(int)(tileW()*e.kind.size*.70);int bob=(int)(Math.sin(game.time*8+e.seed*9)*2);g.setColor(new Color(17,24,17,110));g.fillOval((int)p.x-s,(int)p.y-s/5,s*2,s/3);g.setColor(new Color(e.kind.color));g.fillOval((int)p.x-s/2,(int)p.y-s+bob,s,s);g.setColor(new Color(70,65,50));for(int side:new int[]{-1,1}){g.setStroke(new BasicStroke(2));g.drawLine((int)p.x+side*s/3,(int)p.y-s/2+bob,(int)p.x+side*s/2,(int)p.y-s/3+bob);g.setColor(new Color(229,205,160));g.fillOval((int)p.x+side*s/5-2,(int)p.y-s*3/4+bob,4,4);}g.setColor(new Color(32,43,31,210));g.fillRoundRect((int)p.x-s/2,(int)p.y-s-9,s,4,3,3);g.setColor(e.hp/e.maxHp>.35?new Color(204,222,153):new Color(213,133,108));g.fillRoundRect((int)p.x-s/2,(int)p.y-s-9,(int)(s*Math.max(0,e.hp/e.maxHp)),4,3,3);if(e.kind==EnemyKind.BOSS){g.setColor(new Color(206,180,130));g.drawArc((int)p.x-s/2-3,(int)p.y-s-5,s+6,s,0,180);}}
    private void paintProjectile(Graphics2D g,Projectile p){Point2D.Double a=project(p.x+8,p.z+6);double lift=p.y*tileH()*.55;int x=(int)a.x,y=(int)(a.y-lift),r=p.kind==TowerKind.CANNON?7:4;g.setColor(new Color(p.kind.color, true));g.setColor(new Color(p.kind.color));g.fillOval(x-r,y-r,r*2,r*2);g.setColor(new Color(250,245,208,100));g.drawLine(x-r*2,y+4,x+r*2,y-4);}
    private void paintEffects(Graphics2D g){for(Invader e:game.enemies)if(e.slowUntil>game.time){Point2D.Double p=project(e.x+8,e.z+6);g.setColor(new Color(132,208,225,135));g.drawOval((int)p.x-13,(int)p.y-23,26,26);} }
    private void paintVignette(Graphics2D g){g.setPaint(new GradientPaint(0,0,new Color(20,27,21,35),0,getHeight(),new Color(19,27,22,105)));g.fillRect(0,0,getWidth(),getHeight());}
    public static Color color(int rgb){return new Color(rgb);}
}
